import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{t}from"./book-open-check-9oxAPU5G.js";import{A as n,C as r,E as i,M as a,N as o,O as s,P as c,b as l,k as u,l as d,n as f,o as p,p as m,t as h,v as g,w as _}from"./shared-BLp3PbbW.js";import{t as v}from"./database-B9dOoFl-.js";import{t as y}from"./shield-check-DLlmt4Nd.js";import{t as b}from"./CodeEditor-DqHMt3P8.js";var x=e();function S({module:e}){return(0,x.jsxs)(o,{children:[(0,x.jsx)(a,{variant:`project`,chip:e??`Блок 11 · Проверенный вход и CRUD Planner API`,title:`Полная замена в сервисе`,intro:`В прошлом шаге мы проверили сохранение Task в JSON. Теперь добавим полную замену: изменим title, priority и is_done, сохранив id, tags и соседние записи.`,tags:[{icon:(0,x.jsx)(t,{size:14}),label:`одна существующая Task`},{icon:(0,x.jsx)(v,{size:14}),label:`тот же JsonStorage`},{icon:(0,x.jsx)(y,{size:14}),label:`проверка до сохранения`}]}),(0,x.jsxs)(c,{number:`00`,title:`От сохранения к замене`,children:[(0,x.jsx)(s,{children:`Мы умеем создавать Task и сохранять её в JSON. Теперь изменим существующую задачу, не создавая новую.`}),(0,x.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`PlannerService работает с JsonStorage; тест уже проверял чтение того же файла новым сервисом.`},{title:`Новый вопрос`,description:`Как изменить title, priority и is_done, сохранив id, tags и соседние записи?`},{title:`Результат`,description:`Добавим и проверим replace_task. В следующем шаге подключим его к HTTP PUT.`}]}),(0,x.jsx)(`p`,{children:`Маршрут: определить границу полей, найти запись, собрать допустимую Task, заменить её позицию и проверить сохранённый файл.`}),(0,x.jsx)(i,{tone:`info`,children:`В этом шаге реализуем и проверим сервисный метод. HTTP-схемы и маршрут появятся в следующем шаге.`})]}),(0,x.jsxs)(c,{number:`01`,title:`Меняем поля, сохраняя запись`,children:[(0,x.jsx)(s,{children:`При полной замене передаём все редактируемые поля, но оставляем id и tags прежними.`}),(0,x.jsx)(`p`,{children:`У Planner уже есть Task. Меняем её title, priority и is_done. id указывает, какую задачу нашли; tags остаются внутренними метками и не задаются заново. Поэтому здесь заменяется изменяемая часть существующей записи, а не вся структура Task: если создать объект с новым id, список получит другую задачу. Если взять tags из входа вместо текущего объекта, можно потерять внутренние метки. Сервис берёт обе сохраняемые части у найденной Task, чтобы они не зависели от присланных редактируемых значений.`}),(0,x.jsx)(`p`,{children:`Представим карточку книги: мы меняем название и статус выдачи, но инвентарный номер и метки остаются прежними. Так и в Planner: меняются поля задачи, а сама запись остаётся той же.`}),(0,x.jsx)(n,{rows:[[(0,x.jsx)(`code`,{children:`title, priority, is_done`}),`Новые значения из договора полной замены`],[(0,x.jsx)(`code`,{children:`id`}),`Берём у найденной Task, чтобы не создать другую запись`],[(0,x.jsx)(`code`,{children:`tags`}),`Переносим из найденной Task, клиент их здесь не задаёт`]]}),(0,x.jsx)(`p`,{children:"Создание добавляет запись, а замена находит существующую по id. Полная замена получает все три редактируемых поля сразу; если изменить только одно, это уже частичное изменение из следующего занятия. Звёздочка в сигнатуре `replace_task(task_id, *, title, priority, is_done)` отделяет позиционные параметры от параметров, которые можно передать только по имени. Значит, вызов будет выглядеть как `replace_task(11, title=..., priority=..., is_done=...)`: сначала передаём id, а остальные значения подписываем. Python не позволит случайно переставить три похожих значения местами, передав их просто через запятую. Это правило вызова метода, а не часть данных Task."}),(0,x.jsx)(b,{caption:`независимый пример с карточкой оборудования`,code:`equipment = {"id": 28, "name": "Сканер", "status": "ready", "labels": ["office"]}
replacement = {"id": equipment["id"], "name": "Сканер 2", "status": "checked", "labels": equipment["labels"].copy()}
print(replacement)  # {'id': 28, 'name': 'Сканер 2', 'status': 'checked', 'labels': ['office']}`}),(0,x.jsx)(`p`,{children:`Вывод показывает новые name и status при прежних id и labels. Это пример границы замены на другом сюжете; он не описывает внутреннее устройство Planner.`})]}),(0,x.jsxs)(c,{number:`02`,title:`Найти задачу в существующем сервисе`,children:[(0,x.jsx)(s,{children:`PlannerService отвечает за предметное изменение, а JsonStorage читает и сохраняет полный список.`}),(0,x.jsx)(`p`,{children:`storage.load() читает актуальный список, а _find_task(tasks, task_id) ищет в нём объект по постоянному id. Это не номер позиции: например, id 11 может стоять на индексе 1. Список содержит объекты Task, поэтому позицию найденного объекта получают как tasks.index(current), а не tasks.index(task_id). Эти два числа отвечают на разные вопросы: id остаётся идентификатором записи, а индекс сообщает, где объект находится в текущем списке. Список может измениться или быть переставлен, поэтому метод каждый раз загружает его заново, ищет объект по id и только затем получает актуальный индекс. Так он меняет нужную запись, даже если её место не совпадает с id.`}),(0,x.jsx)(b,{caption:`позиция в независимом списке`,code:`task_ids = [4, 11]
position = task_ids.index(11)
print(position)  # 1`}),(0,x.jsx)(`p`,{children:`В каждом вызове заново загружаем список и находим позицию: она может измениться после перестановки записей, тогда как id остаётся прежним.`}),(0,x.jsx)(m,{prompt:`Соединим знакомую границу и её результат`,leftTitle:`Часть сервиса`,rightTitle:`Что происходит`,pairs:[{left:`storage.load()`,right:`Получаем полный список из хранилища`},{left:`_find_task(...)`,right:`Находим Task по постоянному id`},{left:`Task(...)`,right:`Проверяем новую доменную запись`},{left:`TaskNotFoundError`,right:`Сообщаем, что id отсутствует`}],explanation:`Сервис использует одно хранилище и один поиск. Ошибка отсутствующей задачи возникает до построения новой записи, а ошибка чтения файла остаётся отдельным StorageError.`}),(0,x.jsx)(`p`,{children:`TaskNotFoundError означает: список успешно прочитан, но нужного id в нём нет. StorageError означает, что JsonStorage не смог прочитать или записать данные. Это не одна и та же ситуация: при TaskNotFoundError мы знаем, что поиск завершился по настоящему списку, а при StorageError содержимое может быть недоступно. Не подменяем сбой чтения пустым списком и не создаём новую запись автоматически: так можно скрыть исходные данные и превратить ошибку чтения в неверное изменение.`}),(0,x.jsx)(l,{question:`Что делает replace_task, если положительный id не найден?`,options:[`Поднимает TaskNotFoundError и не добавляет новую запись`,`Создаёт Task с переданным id`,`Возвращает пустой список вместо ошибки`],correctIndex:0,explanation:`Если id не найден, _find_task поднимает TaskNotFoundError. Создание остаётся отдельной операцией add_task.`})]}),(0,x.jsxs)(c,{number:`03`,title:`Сначала собрать проверенную Task`,children:[(0,x.jsx)(s,{children:`Найденная запись ещё не изменена. Сначала мы готовим её допустимую новую версию.`}),(0,x.jsx)(`p`,{children:"Перед изменением списка создаём новую Task: берём прежний id, новые title, priority и is_done, а tags копируем вызовом current.tags.copy(). Копия нужна потому, что список изменяемый; метки остаются теми же, но принадлежат новому объекту отдельно. Строки внутри списка неизменяемы, поэтому глубже копировать их не требуется. Простое присваивание `new_tags = current.tags` связало бы оба имени с одним и тем же списком. Тогда добавление метки в новой Task изменило бы список исходной Task тоже. Метод copy() создаёт новый список, поэтому можно перенести все текущие метки, не оставляя общей изменяемой коллекции. Сами теги здесь не редактируются и не сортируются."}),(0,x.jsx)(`p`,{children:"Конструктор проверяет доменные правила сразу. Например, priority=6 вне допустимого диапазона 1–5 вызывает ValueError: новая Task не создаётся, а исходный список ещё не затронут. Это похоже на проверку черновика карточки оборудования перед заменой действующей; аналогия касается только порядка действий. Python сначала вычисляет аргументы и выполняет вызов Task(...), а следующая строка метода запускается лишь после успешного возврата конструктора. Поэтому при ValueError управление не дойдёт до присваивания `tasks[index] = updated` и до `save()`. Мы не исправляем неверное значение и не скрываем исключение внутри предметного метода: причину отказа получает вызывающий код."}),(0,x.jsx)(g,{code:`labels = ["api", "review"]
current = {"id": 7, "labels": labels}
new_labels = current["labels"].copy()
replacement = {"id": current["id"], "labels": new_labels}
replacement["labels"].append("tests")
print(current["labels"])
print(replacement["labels"])`,steps:[{line:1,note:`У карточки id 7 есть список labels.`,vars:{current:`{'id': 7, 'labels': ['api', 'review']}`}},{line:2,note:`copy() создаёт отдельный список меток.`,vars:{"current['labels']":`['api', 'review']`,new_labels:`['api', 'review']`}},{line:3,note:`Новая карточка сохраняет id и получает копию списка.`,vars:{replacement:`{'id': 7, 'labels': ['api', 'review']}`}},{line:4,note:`Добавляем метку в новый список.`,vars:{"replacement['labels']":`['api', 'review', 'tests']`}},{line:5,note:`В исходном списке этой метки нет.`,vars:{"current['labels']":`['api', 'review']`}},{line:6,note:`В новой карточке метка есть.`,vars:{"replacement['labels']":`['api', 'review', 'tests']`}}]}),(0,x.jsx)(`p`,{children:`Применим это к Task: новые поля и отдельная копия tags входят в конструктор до присваивания в список.`}),(0,x.jsx)(r,{code:`current.title = "Reviewed API"
self.storage.save(tasks)
updated = Task(
    id=current.id,
    title=current.title,
    priority=6,
    is_done=True,
    tags=current.tags.copy(),
)`,question:`Предположим, что priority=6 не проходит правило доменной Task. Почему порядок опасен?`,options:[`Новое название уже сохранено со старым приоритетом, затем конструктор завершается ошибкой`,`save автоматически создаст новый id для прежней Task`,`copy() удалит все строки из tags`],correctIndex:0,explanation:`Список и файл сохранены до проверки новой Task. Если конструктор отклонит priority, получится частичное изменение. Сначала проверяем Task, затем меняем список и сохраняем.`,fix:`updated = Task(
    id=current.id,
    title="Reviewed API",
    priority=6,
    is_done=True,
    tags=current.tags.copy(),
)
tasks[index] = updated
self.storage.save(tasks)`})]}),(0,x.jsxs)(c,{number:`04`,title:`Заменить одну позицию и сохранить список`,children:[(0,x.jsx)(s,{children:`После проверки Task заменим одну позицию и сохраним полный список через тот же storage.`}),(0,x.jsx)(`p`,{children:"После успешного создания Task заменяем ровно одну позицию в загруженном списке, один раз сохраняем весь список и возвращаем эту Task. Добавление в конец создало бы дубликат id; сохранение до проверки могло бы оставить частичное изменение. До вызова `storage.save(tasks)` новое состояние существует только в памяти процесса: присваивание по индексу само по себе не меняет JSON-файл. Поэтому сохранение выполняется после замены и только один раз. Возвращённый объект сообщает вызывающему коду, что метод подготовил как результат операции, но именно повторное чтение файла подтверждает, что состояние пережило завершение текущего вызова. Если `save()` завершится с ошибкой, метод не обещает транзакционный откат уже записанного файла."}),(0,x.jsx)(_,{title:`Порядок полной замены`,prompt:`Расставим действия сервиса по порядку`,pieces:[{id:`find`,code:`Найти Task по id в загруженном списке`},{id:`build`,code:`Создать новую Task с прежним id и tags`},{id:`replace`,code:`Заменить найденный элемент списка`},{id:`save`,code:`Сохранить полный список через JsonStorage`},{id:`return`,code:`Вернуть новую Task вызывающему коду`}],correctOrder:[`find`,`build`,`replace`,`save`,`return`],explanation:`Сначала ищем Task и проверяем новые значения. Затем меняем список, сохраняем JSON и возвращаем новую Task.`,incorrectExplanation:`Сначала найдём Task и проверим её новую версию. Потом заменим одну позицию, сохраним список один раз и вернём Task.`}),(0,x.jsx)(h,{caption:`Путь полной замены через PlannerService`,children:(0,x.jsxs)(p,{label:`От чтения полного списка к проверенной замене и возврату результата`,children:[(0,x.jsx)(d,{title:`JsonStorage`,shape:`database`,children:(0,x.jsx)(`p`,{children:`load() возвращает полный список`})}),(0,x.jsx)(f,{label:`найти запись`}),(0,x.jsx)(d,{title:`PlannerService`,children:(0,x.jsx)(`p`,{children:`_find_task и текущая позиция`})}),(0,x.jsx)(f,{label:`собрать до изменения`}),(0,x.jsx)(d,{title:`Новая Task`,children:(0,x.jsx)(`p`,{children:`Конструктор проверяет поля`})}),(0,x.jsx)(f,{label:`проверка прошла`}),(0,x.jsx)(d,{title:`Список Planner`,children:(0,x.jsx)(`p`,{children:`Одна позиция заменена`})}),(0,x.jsx)(f,{label:`сохранить один раз`}),(0,x.jsx)(d,{title:`JsonStorage`,shape:`database`,children:(0,x.jsx)(`p`,{children:`save() записывает полный список`})}),(0,x.jsx)(f,{label:`вернуть`}),(0,x.jsx)(d,{title:`Результат`,shape:`terminator`,children:(0,x.jsx)(`p`,{children:`Новая Task для вызывающего кода`})})]})}),(0,x.jsx)(`p`,{children:`Два отказа до сохранения различаются по причине: _find_task сообщает TaskNotFoundError при неизвестном id, а конструктор сообщает ValueError при недопустимом поле. Сбой чтения или записи остаётся StorageError; метод его не маскирует и не обещает откат файла после ошибки save. В первых двух случаях мы можем гарантировать, что до ошибки не меняли список и не вызывали сохранение: поиск остановился раньше конструктора, либо конструктор не создал допустимую Task. При StorageError гарантия уже другая: это ошибка работы с хранилищем, а не основание подменить её одним из предметных исключений. Так вызывающий код может отличить неверный запрос к сервису от сбоя файла.`}),(0,x.jsx)(`p`,{children:`PlannerService выполняет предметную замену независимо от вызывающего интерфейса. На следующем шаге HTTP PUT передаст значения этому готовому методу, не дублируя поиск и сохранение JSON.`})]}),(0,x.jsxs)(c,{number:`05`,title:`Проверить сервис на отдельном файле`,children:[(0,x.jsx)(s,{children:`Проверим и ответ метода, и сохранённый файл.`}),(0,x.jsx)(`p`,{children:'Каждый тест использует JsonStorage(tmp_path / "tasks.json"): pytest создаёт отдельное временное место, поэтому рабочий Planner не затрагивается. В успешном сценарии заменяем задачу 11, проверяем возвращённую Task целиком, затем открываем тот же файл новым PlannerService и сравниваем весь список с ожидаемым: задача 4 и порядок сохранены, лишней записи нет. Здесь нужны обе проверки. Сравнение `updated == expected` проверяет, что публичный метод вернул правильный объект с новым title, priority и is_done и прежними id/tags. Новый сервис проверяет уже границу хранения, а полное сравнение списка замечает потерю соседа, дубликат или повреждённые поля. Если проверить только ответ метода, можно не заметить, что обновление осталось лишь в памяти.'}),(0,x.jsx)(`p`,{children:`В отказном сценарии id 404 должен дать TaskNotFoundError, а для существующей задачи с priority=6 ожидаем ValueError. После каждого вызова новый сервис перечитывает файл и сравнивает его с исходным списком. Команда плана запускается из StudyHub: python -m pytest tests/test_services.py. Два вызова проверяют разные места остановки: для id 404 конструктор новой Task вообще не нужен, а для найденного id ошибка возникает во время доменной проверки priority. В обоих случаях неизменность файла подтверждает, что ошибочное действие не сохранило новую запись. Эти тесты проверяют публичное поведение сервиса и повторное чтение, а не повторяют его внутренний алгоритм в тесте.`}),(0,x.jsx)(l,{question:`Какой результат сильнее подтверждает сохранённую замену?`,options:[`Метод вернул Task с новым title`,`Новый PlannerService прочитал тот же tmp_path и увидел полную Task и прежнего соседа`,`В файле осталось столько же строк`],correctIndex:1,explanation:`Ответ метода проверяет результат вызова. Новый сервис проверяет файл. Сравнение обеих Task подтверждает, что цель заменена, а сосед сохранился.`}),(0,x.jsx)(i,{tone:`info`,children:`Проверка относится к последовательным вызовам. Она не доказывает безопасность одновременной записи из нескольких процессов и не обещает rollback при файловой ошибке.`})]}),(0,x.jsxs)(c,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(s,{children:`В трёх заданиях добавим метод, проверим успешное сохранение и проверим отказы.`}),(0,x.jsx)(u,{variant:`connected`,items:[{title:`1. Добавим replace_task`,description:`Используем load() и _find_task. Создадим Task с прежними id и tags, заменим одну позицию и сохраним список.`},{title:`2. Проверим успешную замену`,description:`Новый сервис прочитает задачу 11 с новыми полями и прежними id/tags. Задача 4 останется без изменений.`},{title:`3. Проверим ошибки`,description:`id 404 вызовет TaskNotFoundError, priority 6 вызовет ValueError. После ошибок список останется прежним.`},{title:`Передадим готовый сервис`,description:`В следующем шаге PUT вызовет готовый метод; маршрут не будет повторять поиск и сохранение JSON.`}]}),(0,x.jsx)(`p`,{children:`В первом задании добавим replace_task, во втором проверим успешное сохранение, в третьем проверим два отказа. HTTP PUT подключается только в следующем уроке.`})]})]})}export{S as Lesson53};